import{_ as e,o as a,c as s,ah as o}from"./chunks/framework.ChH6X6u6.js";const u=JSON.parse('{"title":"Timetables","description":"","frontmatter":{"layout":"doc"},"headers":[],"relativePath":"en/guide/admin/emplois-du-temps.md","filePath":"src/en/guide/admin/emplois-du-temps.md"}'),i={name:"en/guide/admin/emplois-du-temps.md"};function l(r,t,n,d,h,c){return a(),s("div",null,[...t[0]||(t[0]=[o('<h1 id="timetables" tabindex="-1">Timetables <a class="header-anchor" href="#timetables" aria-label="Permalink to &quot;Timetables&quot;">​</a></h1><p>This page covers building a class&#39;s weekly timetable. It assumes the class already exists and that at least one teacher is assigned to it (see <a href="/era-guide/en/guide/admin/personnel-utilisateurs.html">Staff and user accounts</a>) — without a teacher assignment, you can&#39;t add any slot.</p><h2 id="build-a-class-s-timetable" tabindex="-1">Build a class&#39;s timetable <a class="header-anchor" href="#build-a-class-s-timetable" aria-label="Permalink to &quot;Build a class&#39;s timetable&quot;">​</a></h2><p>From <strong>School setup → Classes</strong>, click <strong>Timetable</strong> on the row for the class you want.</p><p>To add a slot:</p><ol><li>Click <strong>Add slot</strong>.</li><li>Fill in the fields below.</li><li>Repeat for each slot of the week. The trash-can button on a row removes that slot from the form.</li><li>Click <strong>Save</strong>.</li></ol><table tabindex="0"><thead><tr><th>Field</th><th>Detail</th></tr></thead><tbody><tr><td>Day</td><td>Monday through Sunday</td></tr><tr><td>Start time</td><td>—</td></tr><tr><td>End time</td><td>—</td></tr><tr><td>Teacher / subject</td><td>list of existing teacher assignments for this class; an assignment with no subject (qualitative class) is shown as &quot;Generalist&quot;</td></tr></tbody></table><p>If no teacher is assigned to the class yet, a message tells you so and the <strong>Add slot</strong> button stays disabled — go create the necessary teacher assignments first.</p><h2 id="export-the-timetable" tabindex="-1">Export the timetable <a class="header-anchor" href="#export-the-timetable" aria-label="Permalink to &quot;Export the timetable&quot;">​</a></h2><p>The <strong>Export to calendar</strong> button (top of the page) downloads the class&#39;s timetable in a calendar format that can be imported into a calendar app.</p>',10)])])}const p=e(i,[["render",l]]);export{u as __pageData,p as default};
